def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the color used for full-height and full-width dividers.
    divider = None
    for color in range(10):
        if any(all(v == color for v in row) for row in g) and \
           any(all(g[r][c] == color for r in range(h)) for c in range(w)):
            divider = color
            break
    if divider is None:
        return g

    sep_rows = [r for r in range(h) if all(v == divider for v in g[r])]
    sep_cols = [c for c in range(w) if all(g[r][c] == divider for r in range(h))]

    def intervals(length, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < length:
            result.append((start, length))
        return result

    row_boxes = intervals(h, sep_rows)
    col_boxes = intervals(w, sep_cols)

    def pattern(r0, r1, c0, c1):
        return frozenset(
            (r - r0, c - c0, g[r][c])
            for r in range(r0, r1)
            for c in range(c0, c1)
            if g[r][c] != 0 and g[r][c] != divider
        )

    # Identify neighboring box boundaries that show a reflected matching pair.
    mirror_boundaries = set()
    for j in range(len(col_boxes) - 1):
        left, right = col_boxes[j], col_boxes[j + 1]
        width = left[1] - left[0]
        if width != right[1] - right[0]:
            continue
        for r0, r1 in row_boxes:
            a = pattern(r0, r1, left[0], left[1])
            b = pattern(r0, r1, right[0], right[1])
            reflected_b = frozenset((y, width - 1 - x, color) for y, x, color in b)
            if a and a == reflected_b:
                mirror_boundaries.add(j)
                break

    # Complete each reflected pair wherever one of its boxes is empty.
    for j in mirror_boundaries:
        left, right = col_boxes[j], col_boxes[j + 1]
        width = left[1] - left[0]
        for r0, r1 in row_boxes:
            a = pattern(r0, r1, left[0], left[1])
            b = pattern(r0, r1, right[0], right[1])
            if bool(a) == bool(b):
                continue
            if a:
                for y, x, color in a:
                    g[r0 + y][right[0] + width - 1 - x] = color
            else:
                for y, x, color in b:
                    g[r0 + y][left[0] + width - 1 - x] = color

    return g
